def place(t, x, y):
    """Put twilight point `t` at (x, y) F26Dot6: SCFS along x then y, with zp2 = 0, org = cur."""
    return "PUSHB 0 SZP2 SVTCA[x] PUSHB %d PUSHW %d SCFS SVTCA[y] PUSHB %d PUSHW %d SCFS" % (t, x, t, y)


