# ----------------------------------------------------------------------------------------------
# Running a program through FreeType
# ----------------------------------------------------------------------------------------------
def hint_once(code, ppem, font, gid=1, comp=b"", comp3=b""):
    """FreeType's answer for glyph `gid` of font variant `font` at `ppem`, with `code` as glyph
    1's program and `comp` / `comp3` as glyph 2's / 3's composite programs: the unhinted outline,
    then the hinted points/tags/advance from a fresh face, then the same load under
    FT_LOAD_PEDANTIC on ANOTHER fresh face (the flag is sticky per size), which must succeed."""
    data = build_font(code, max_program_len(), font, comp, comp3)
    face = ftshim.load_face(data)
    raw = ftshim.hinted(face, ppem, gid, hint=False)
    points, tags, advance = ftshim.hinted(face, ppem, gid)
    ftshim.done(face)
    strict = ftshim.load_face(data)
    try:
        p2, t2, a2 = ftshim.hinted(strict, ppem, gid, pedantic=True)
    finally:
        ftshim.done(strict)
    assert (p2, t2, a2) == (points, tags, advance), "pedantic and default loads disagree"
    n = len(outlines_of(font)[gid][0])
    assert len(points) == n, (gid, len(points), n)
    return {"code": code, "raw": raw, "points": points, "tags": tags, "advance": advance, "gid": gid,
            "n": len(points), "comp": comp, "comp3": comp3}


def load_sequence(data, ppem, gids, pedantic=False):
    """FreeType driven the CONSUMER's way (round 5): ONE face, the pixel size set ONCE, then the
    glyphs loaded in `gids` order on that size — `prep` runs before the first load only, and the
    size's cvt, storage and twilight zone carry from load to load exactly as rekha's context keeps
    them. ftshim.load_glyph requests the size only when the ppem changes (Face.ppem), so the loads
    after the first share it. Answers, per gid, (points, tags, ends, advance) or the FTError that
    refused the load (which leaves the size's state as it is, as it would for a consumer)."""
    face = ftshim.load_face(data)
    out = []
    try:
        ftshim.set_size(face, ppem)
        flags = ftshim.FT_LOAD_PEDANTIC if pedantic else 0
        for gid in gids:
            try:
                out.append(ftshim.load_glyph(face, ppem, gid, flags))
            except ftshim.FTError as e:
                out.append(e)
    finally:
        ftshim.done(face)
    return out


def consumer_flow(prog, r):
    """The round-5 companions of a row: FreeType's gid 1, 2 and 3 of the row's font, loaded in
    that order on one face at the row's ppem (load_sequence), the same again on a fresh face
    under FT_LOAD_PEDANTIC — the two must agree, or the gid is 'not recorded' with the refusal as
    its reason. Records r["seq"] = {gid: (points, tags, ends, advance) or None}, r["seq_why"] =
    {gid: reason}, and r["seq_carries"] = the gids whose consumer-flow numbers differ from the
    same glyph loaded FIRST on a fresh face (state carried from an earlier load in the sequence:
    twilight points, a WCVTF into the size's cvt)."""
    data = build_font(r["code"], max_program_len(), prog["font"], r["comp"], r["comp3"])
    gids = (1, 2, 3)
    plain = load_sequence(data, prog["ppem"], gids)
    strict = load_sequence(data, prog["ppem"], gids, pedantic=True)
    r["seq"], r["seq_why"], r["seq_carries"] = {}, {}, []
    for gid, a, b in zip(gids, plain, strict):
        if isinstance(b, ftshim.FTError):
            r["seq"][gid] = None
            r["seq_why"][gid] = "FT_LOAD_PEDANTIC refuses gid %d in the sequence (%s)" % (gid, b)
            continue
        if isinstance(a, ftshim.FTError):
            sys.exit("program %s: gid %d loads under PEDANTIC but not in the default mode (%s)" % (prog["name"], gid, a))
        assert a == b, "program %s: gid %d differs between the default and the pedantic sequence" % (prog["name"], gid)
        r["seq"][gid] = a
        n = len(outlines_of(prog["font"])[gid][0])
        assert len(a[0]) == n, (prog["name"], gid, len(a[0]), n)
        first = load_sequence(data, prog["ppem"], (gid,))[0]
        if first != a:
            r["seq_carries"].append(gid)
    own = r["seq"][prog["gid"]]
    if prog["gid"] == 1 or prog["gid"] not in r["seq_carries"]:
        assert own is not None and own[:2] == (r["points"], r["tags"]) and own[3] == r["advance"], \
            "program %s: the sequence's gid %d differs from the row's own load" % (prog["name"], prog["gid"])
    return r


def run_program(prog):
    """Hint `prog` on its font variant at its ppem, pedantic-clean or the script stops; then its
    consumer-flow companions (gid 1, 2, 3 in order on one face)."""
    try:
        r = hint_once(asm(prog["text"]), prog["ppem"], prog["font"], prog["gid"],
                      asm(prog["comp"]) if prog["comp"] else b"", asm(prog["comp3"]) if prog["comp3"] else b"")
    except ftshim.FTError as e:
        sys.exit("program %s: FreeType refused it under FT_LOAD_PEDANTIC (%s) - fix the program" % (prog["name"], e))
    r["font"] = prog["font"]
    return consumer_flow(prog, r)


def max_program_len():
    lens = [len(asm(p["text"])) for p in PROGRAMS]
    lens += [len(asm(p["comp"])) for p in PROGRAMS if p["comp"]] + [len(asm(p["comp3"])) for p in PROGRAMS if p["comp3"]]
    lens += [len(prep_bytes(f)) for f in range(len(FONTS))] + [len(fpgm_bytes(f)) for f in range(len(FONTS))]
    lens += [len(glyph4_bytes(f)) for f in range(len(FONTS))]
    return max(lens + [16])


def base_font(f):
    """Font variant `f` as the module embeds it: glyphs 1, 2 and 3 with NO program (glyph 2 and 3
    keep their WE_HAVE_INSTR flag with n_ins 0 where the variant sets it) and glyph 4, where the
    variant has one, WITH its own program (it is the font's, not a row's), so a consumer sees the
    outlines, the tables and the limits exactly as every program's font had them."""
    return build_font(b"", max_program_len(), f)


def scaled_outline(ppem):
    s = scale_for(ppem)
    return [(mulfix(x, s), mulfix(y, s)) for x, y, _ in OUTLINE]


# ----------------------------------------------------------------------------------------------
# Non-degeneracy checks: what the WRONG reading of a row would give, asserted != FreeType's.
# ----------------------------------------------------------------------------------------------
def _org():
    return scaled_outline(12)


def _orus():
    return [(x, y) for x, y, _ in OUTLINE]


def check_mdrp_orus(r):
    org = _org()
    wrong = org[0][0] + (org[3][0] - org[0][0])  # org - org: the point would not move at all
    assert r["points"][3][0] != wrong, "mdrp_orus: org and orus readings coincide, pick other points"


def check_md_orus(r):
    org = _org()
    wrong = org[3][0] - org[0][0]
    assert r["points"][13][0] != wrong, "md_orus: org and orus readings coincide"


def check_ip_orus(r):
    org = _org()
    cur_range = r["points"][1][0] - org[0][0]
    for p in (2, 9):
        wrong = org[0][0] + muldiv(org[p][0] - org[0][0], cur_range, org[1][0] - org[0][0])
        assert r["points"][p][0] != wrong, "ip_orus: point %d agrees with the org reading" % p


def check_isect(r):
    """Both ISECT branches are taken: the first crossing is far from grazing, the second is."""
    org = _org()
    pp = [(mulfix(x, scale_for(12)), mulfix(y, scale_for(12))) for x, y in phantoms()]
    pp[0] = (pix_round(pp[0][0]), 0)
    pp[1] = (pix_round(pp[1][0]), 0)
    pts = org + pp

    def grazing(a0, a1, b0, b1):
        dbx, dby = pts[b1][0] - pts[b0][0], pts[b1][1] - pts[b0][1]
        dax, day = pts[a1][0] - pts[a0][0], pts[a1][1] - pts[a0][1]
        disc = muldiv(dax, -dby, 0x40) + muldiv(day, dbx, 0x40)
        dot = muldiv(dax, dbx, 0x40) + muldiv(day, dby, 0x40)
        return not (19 * abs(disc) > abs(dot))

    assert not grazing(0, 4, 2, 6), "isect: lines 0-4 and 2-6 count as grazing"
    assert grazing(0, 2, PP1, PP2), "isect: lines 0-2 and pp1-pp2 do not take the /4 fallback"


def check_near_perp(r):
    fx1 = normalize(1, 20)[0]
    fx2 = normalize(1, 12)[0]
    assert -0x400 < fx1 < 0x400, "near_perp: (1, 20) is not in the orthogonal band (%d)" % fx1
    assert fx2 >= 0x400, "near_perp: (1, 12) is in the orthogonal band (%d)" % fx2
    assert r["points"][2] == r["raw"][0][2] and r["tags"][2] == 1, "near_perp: point 2 moved or was touched"
    assert r["points"][4] != r["raw"][0][4] and r["tags"][4] & 0x18 == 0x18, "near_perp: point 4 did not move"


def check_b1(r):
    org = _org()
    pv = normalize(36, 35)[:2]
    fdp = (pv[0] * 0x4000 + 0x2000) >> 14
    move = 175 - dotfix14(org[9][0] - org[0][0], org[9][1] - org[0][1], pv[0], pv[1])
    assert move == 19, "b1: the MSIRP moves by %d, not 19" % move
    wrong = org[9][0] + muldiv(move, 0x4000, fdp)  # 2.13.2's FT_MulDiv(d, fv, F_dot_P)
    assert r["points"][9][0] != wrong, "b1: 2.13.2 and 2.14.3 agree on this move, pick another"


def check_fdotp_edge(r):
    org = _org()
    pv = normalize(64, 1)[:2]
    fdp = (pv[0] * 0x4000 + 0x2000) >> 14
    assert fdp == 0x3FFE, "fdotp_edge: F_dot_P is 0x%X, not 0x3FFE" % fdp
    move = 24576 - dotfix14(org[9][0] - org[0][0], org[9][1] - org[0][1], pv[0], pv[1])
    wrong = org[9][0] + mulfix(move, (0x4000 * 0x10000) // fdp)  # the general regime
    assert r["points"][9][0] != wrong, "fdotp_edge: the fast path and the general path agree here"


def check_normlen(r):
    org = _org()
    dx, dy = org[0][0] - org[3][0], org[0][1] - org[3][1]
    vx, vy, l = normlen(dx, dy)
    assert l > 0x10000, "normlen: the 0-3 line prenormalises to %d, not over 0x10000" % l
    port = (int(vx / 4), int(vy / 4))
    got = (r["points"][13][0], r["points"][12][0])
    assert got == port, "normlen: the FT_Vector_NormLen port answers %s, FreeType %s" % (port, got)


def check_sdpvtl(r):
    org = _org()
    orus = _orus()
    s = scale_for(12)
    cur4 = (org[4][0] + 300, org[4][1])
    proj = normalize(org[0][0] - cur4[0], org[0][1] - cur4[1])[:2]
    fdp = (proj[0] * 0x4000 + 0x2000) >> 14
    mv = int((0x4000 * 0x10000) / fdp)
    org_dist = mulfix(dotfix14(orus[9][0] - orus[0][0], orus[9][1] - orus[0][1], proj[0], proj[1]), s)
    cur_dist = dotfix14(org[9][0] - org[0][0], org[9][1] - org[0][1], proj[0], proj[1])
    wrong = org[9][0] + mulfix(org_dist - cur_dist, mv)  # the projection used as the dual too
    assert r["points"][9][0] != wrong, "sdpvtl: dual and projection readings agree here"


def check_sloop_order(r, prog):
    """The loop instruction took the TOP n values: the first value pushed (the leftover) is the
    one SHPIX moved by exactly 64 along the axis, and none of the loop's points moved by that."""
    toks = prog["text"].split()
    n = int(toks[toks.index("SLOOP") - 1])
    at = toks.index("SLOOP") + 2
    assert toks[at - 1] == "PUSHB", prog["name"]
    pushed = [int(t) for t in toks[at : at + n + 1]]
    leftover, looped = pushed[0], pushed[1:]
    axis = 0 if toks[0] == "SVTCA[x]" else 1
    shift = [0, 0]
    shift[axis] = 64
    d = (r["points"][leftover][0] - r["raw"][0][leftover][0], r["points"][leftover][1] - r["raw"][0][leftover][1])
    assert d == tuple(shift), "%s: the leftover point %d moved by %s, not %s" % (prog["name"], leftover, d, shift)
    for p in looped:
        dp = (r["points"][p][0] - r["raw"][0][p][0], r["points"][p][1] - r["raw"][0][p][1])
        assert dp != tuple(shift), "%s: looped point %d moved by the SHPIX amount; pick another" % (prog["name"], p)
        assert dp != (0, 0) or r["tags"][p] != r["raw"][1][p], "%s: looped point %d unchanged" % (prog["name"], p)


def check_near_vertical(r, prog):
    org = _org()
    pv = normalize(org[4][0] - org[3][0], org[4][1] - org[3][1])
    assert -0x400 < pv[0] < 0x400, "near_vertical: pvx %d is outside the orthogonal band" % pv[0]
    assert r["points"][9] == r["raw"][0][9], "near_vertical: point 9 moved"
    assert r["tags"][9] == r["raw"][1][9] | 0x08, "near_vertical: point 9 tag %d" % r["tags"][9]
    assert r["points"][11] == r["raw"][0][11] and r["tags"][11] == r["raw"][1][11], "near_vertical: 11 moved or touched"
    assert r["points"][2] != r["raw"][0][2], "near_vertical: rp1 (point 2) was not displaced"


def check_xonly_fast(r, prog):
    fv = normalize(236, 1)[:2]
    assert fv == (0x4000, 69), "xonly_fast: SFVFS 236 1 normalises to %s" % (fv,)
    dx9 = r["points"][9][0] - r["raw"][0][9][0]
    assert mulfix(dx9, fv[1] * 4) != 0, "xonly_fast: the general path would not have moved y either"
    assert r["points"][9][1] == r["raw"][0][9][1] and r["tags"][9] == r["raw"][1][9] | 0x08, "xonly_fast: 9"
    assert r["points"][11][1] == r["raw"][0][11][1] and r["tags"][11] == r["raw"][1][11] | 0x18, "xonly_fast: 11"
    dy13 = r["points"][13][1] - r["raw"][0][13][1]
    assert mulfix(dy13, fv[1] * 4) != 0, "xonly_fast: the general path would not have moved x either"
    assert r["points"][13][0] == r["raw"][0][13][0] and r["tags"][13] == r["raw"][1][13] | 0x10, "xonly_fast: 13"


def check_rthg_sround(r, prog):
    """Every rounded distance here differs from what RTG would have given."""
    orus = _orus()
    s = scale_for(12)
    org = _org()

    def rtg(d):
        return pix_round(d) if d >= 0 else -pix_round(-d)

    for ref, p in ((0, 9), (2, 6), (0, 13), (0, 4)):
        d = mulfix(orus[p][0] - orus[ref][0], s)
        wrong = org[ref][0] + rtg(d)
        assert r["points"][p][0] != wrong, "rthg_sround: point %d agrees with RTG (%d)" % (p, wrong)


def check_alignpts_small(r, prog):
    raw = r["raw"][0]
    assert raw[4][0] - raw[3][0] == -3 and raw[4][1] - raw[12][1] == 3, "alignpts_small: the pairs are not 3/64 apart"
    assert r["points"][3][0] == raw[3][0] - 1 and r["points"][4][0] == raw[4][0] + 1, "alignpts_small: x"
    assert r["points"][12][1] == raw[12][1] + 1 and r["points"][4][1] == raw[4][1] - 1, "alignpts_small: y"


def check_isect_parallel(r, prog):
    assert r["points"][13] == (200, 150) and r["points"][12] == (150, 150), "isect_parallel: not the /4 average"
    assert r["tags"][13] & 0x18 == 0x18 and r["tags"][12] & 0x18 == 0x18, "isect_parallel: touch bits"


def _check_sdpvtl_after_mdap(r, rotate):
    """Point 11 was moved by MDAP[1] along x; the 0-11 line then gives the dual from org and the
    projection from cur (rotated a quarter turn when `rotate`); the MDRP to 8 from rp0 = 0 must
    differ from a reading that uses the projection as the dual too."""
    org, orus, s = _org(), _orus(), scale_for(12)
    cur11 = (pix_round(org[11][0]), org[11][1])
    assert r["points"][11][0] == cur11[0], "sdpvtl_mdap: point 11 is at %d, not %d" % (r["points"][11][0], cur11[0])
    dual = normalize(org[0][0] - org[11][0], org[0][1] - org[11][1])[:2]
    proj = normalize(org[0][0] - cur11[0], org[0][1] - cur11[1])[:2]
    if rotate:
        dual, proj = (-dual[1], dual[0]), (-proj[1], proj[0])
    fdp = (proj[0] * 0x4000 + 0x2000) >> 14
    mv = int((0x4000 * 0x10000) / fdp)
    cur_dist = dotfix14(org[8][0] - org[0][0], org[8][1] - org[0][1], proj[0], proj[1])
    right = mulfix(dotfix14(orus[8][0] - orus[0][0], orus[8][1] - orus[0][1], dual[0], dual[1]), s)
    wrong = mulfix(dotfix14(orus[8][0] - orus[0][0], orus[8][1] - orus[0][1], proj[0], proj[1]), s)
    assert right != wrong, "sdpvtl_mdap: the dual and the projection read the same original distance"
    assert r["points"][8][0] == org[8][0] + mulfix(right - cur_dist, mv), "sdpvtl_mdap: the port disagrees on 8"
    assert r["points"][8][0] != org[8][0] + mulfix(wrong - cur_dist, mv), "sdpvtl_mdap: the wrong reading agrees"
    assert r["points"][13][0] != r["points"][12][0], "sdpvtl_mdap: GC[1] and GC[0] of 9 agree"


def check_sdpvtl_mdap0(r, prog):
    _check_sdpvtl_after_mdap(r, False)


def check_sdpvtl_mdap1(r, prog):
    _check_sdpvtl_after_mdap(r, True)


def check_cutin_twins(r, prog):
    org = _org()
    s = scale_for(12)
    cvt = [mulfix(v, s) for v in CVT]
    for p, c in ((2, 8), (9, 10), (4, 8), (13, 10)):
        assert abs(cvt[c] - org[p][0]) > 68, "cutin_twins: MIAP %d/%d differs by %d" % (p, c, cvt[c] - org[p][0])
    for p, c in ((11, 10), (12, 10), (8, 10), (10, 10)):
        d = org[p][0] - org[0][0]
        assert abs(cvt[c] - d) > 68, "cutin_twins: MIRP %d/%d differs by %d" % (p, c, cvt[c] - d)
    x = [pt[0] for pt in r["points"]]
    assert x[2] == cvt[8] and x[13] == cvt[10], "cutin_twins: MIAP[0] did not land on the cvt"
    assert x[9] == pix_round(org[9][0]) and x[4] == org[4][0], "cutin_twins: MIAP[1] did not keep the outline"
    assert x[11] == org[0][0] + cvt[10] and x[10] == org[0][0] + cvt[10], "cutin_twins: MIRP[00000] not on the cvt"
    assert x[12] == org[0][0] + pix_round(org[12][0] - org[0][0]) and x[8] == org[8][0], "cutin_twins: MIRP[00100]"
    assert r["tags"][4] & 0x08 and r["tags"][8] & 0x08, "cutin_twins: the unmoved twins were not touched"


def check_prep_differs(r, prog):
    """The same program on font 0 (prep RTG) must answer differently: the row measures the prep."""
    base = hint_once(r["code"], prog["ppem"], 0)
    assert base["points"] != r["points"], "%s: font 0 gives the same points; the prep is not observed" % prog["name"]


def check_font_differs(r, prog):
    """The same program on font 0 must answer differently or fail to load there (an opcode or a
    function only the variant defines fails the pedantic load): the row measures the variant."""
    try:
        base = hint_once(r["code"], prog["ppem"], 0)
    except (ftshim.FTError, AssertionError):
        return
    assert (base["points"], base["tags"]) != (r["points"], r["tags"]), \
        "%s: font 0 gives the same outline; the variant is not observed" % prog["name"]


# --- the verification round's rows ------------------------------------------------------------
def _org_at(ppem):
    return scaled_outline(ppem)


def _pv_of(prog):
    """The projection vector a fast-path row sets: the SPVFS operands normalised, or SPVTL[0]'s
    deeper-minus-top edge of the scaled outline (ref2143/ttinterp.c Ins_SxVTL: p1 is the deeper
    operand in zp1, p2 the top in zp2, the vector p1 - p2)."""
    toks = prog["text"].split()
    if "SPVFS" in toks:
        k = toks.index("SPVFS")
        return normalize(int(toks[k - 2]), int(toks[k - 1]))[:2]
    k = toks.index("SPVTL[0]")
    org = _org_at(prog["ppem"])
    a, b = org[int(toks[k - 2])], org[int(toks[k - 1])]
    return normalize(a[0] - b[0], a[1] - b[1])[:2]


def _pv_axis(pv):
    """0 when the fast path is Project_x, 1 for Project_y; the row is degenerate otherwise."""
    assert (pv[0] == 0x4000) != (pv[1] == 0x4000), "pv %s selects no single fast path" % (pv,)
    assert pv[0] != 0 and pv[1] != 0, "pv %s is on the axis: fast and general agree" % (pv,)
    return 0 if pv[0] == 0x4000 else 1


def _pv_ops_model(ppem, pv, axis, proj, pts):
    """The pv_*_ops rows under projection `proj`: MSIRP[0] by 400 from rp0 = 0, MDAP[1], MDRP[00100]
    from 0, MIRP[00000] with cvt 8 from 0 (auto-flip on, no cut-in), MIAP[1] with cvt 10 (cut-in 68),
    each on the point `pts` names for it, moved along `axis` alone (F.P is exactly 0x4000). Also
    answers, per point, the general product's excess on the cur-side vector the instruction reads,
    so a coincidence between the two readings is allowed only where that excess is 0."""
    org, orus, s = _org_at(ppem), _orus(), scale_for(ppem)

    def P(a, b=(0, 0)):
        return proj(a[0] - b[0], a[1] - b[1], pv)

    def excess(a, b=(0, 0)):
        return general(a[0] - b[0], a[1] - b[1], pv) - fast(a[0] - b[0], a[1] - b[1], pv)

    msirp, mdap, mdrp, mirp, miap = pts
    out, ex = {}, {}
    out[msirp] = org[msirp][axis] + 400 - P(org[msirp], org[0])
    ex[msirp] = excess(org[msirp], org[0])
    p = P(org[mdap])
    out[mdap] = org[mdap][axis] + rtg(p) - p
    ex[mdap] = excess(org[mdap])
    od = mulfix(P(orus[mdrp], orus[0]), s)
    out[mdrp] = org[mdrp][axis] + rtg(od) - P(org[mdrp], org[0])
    ex[mdrp] = excess(org[mdrp], org[0])
    cvt = mulfix(CVT[8], s)
    od = mulfix(P(orus[mirp], orus[0]), s)
    if (od ^ cvt) < 0:
        cvt = 0 - cvt
    out[mirp] = org[mirp][axis] + cvt - P(org[mirp], org[0])
    ex[mirp] = excess(org[mirp], org[0])
    cvt = mulfix(CVT[10], s)
    p = P(org[miap])
    d = cvt
    if abs(d - p) > 68:
        d = p
    out[miap] = org[miap][axis] + rtg(d) - p
    ex[miap] = excess(org[miap])
    return out, ex


def _assert_fast(r, prog, right, wrong, excess=None):
    """FreeType's answer is the fast-path model on every listed coordinate and differs from the
    general-product model on each, except where the general product's excess is 0 (a coincidence
    the row's comment allows); at least one coordinate must differ."""
    name = prog["name"]
    differ = 0
    for (p, axis), want in right.items():
        got = r["points"][p][axis]
        assert got == want, "%s: point %d %s is %d, the fast-path model says %d" % (name, p, "xy"[axis], got, want)
        if wrong[(p, axis)] != want:
            differ += 1
        else:
            assert excess is not None and excess[(p, axis)] == 0, \
                "%s: point %d agrees with the general product for no reason" % (name, p)
    assert differ > 0, "%s: no coordinate separates the two readings" % name


def check_pv_ops(r, prog):
    pv = _pv_of(prog)
    axis = _pv_axis(pv)
    pts = (5, 4, 6, 7, 11) if axis == 0 else (4, 5, 6, 7, 11)
    right, ex = _pv_ops_model(prog["ppem"], pv, axis, fast, pts)
    wrong, _ = _pv_ops_model(prog["ppem"], pv, axis, general, pts)

    def keyed(d):
        return dict(((p, axis), v) for p, v in d.items())

    _assert_fast(r, prog, keyed(right), keyed(wrong), keyed(ex))


def check_pv_mdap(r, prog):
    """MDAP[1] on each point the row names: cur + (round(proj) - proj) along the axis."""
    pv = _pv_of(prog)
    axis = _pv_axis(pv)
    org = _org_at(prog["ppem"])
    toks = prog["text"].split()
    pts = [int(toks[k - 1]) for k, t in enumerate(toks) if t == "MDAP[1]"]
    right, wrong = {}, {}
    for p in pts:
        for model, proj in ((right, fast), (wrong, general)):
            d = proj(org[p][0], org[p][1], pv)
            model[(p, axis)] = org[p][axis] + rtg(d) - d
    _assert_fast(r, prog, right, wrong)


def check_pv_readout(r, prog):
    """GC[0] / GC[1] / MD[0] of glyph points under the fast PV, then SCFS onto point 1 under the
    SAME projection (SCFS measures point 1 with it too): both steps modelled under each reading."""
    pv = _pv_of(prog)
    assert _pv_axis(pv) == 0
    org = _org_at(12)
    right, wrong = {}, {}
    for model, proj in ((right, fast), (wrong, general)):
        if "MD[0]" in prog["text"]:
            k = proj(org[4][0] - org[0][0], org[4][1] - org[0][1], pv)
        else:
            k = proj(org[4][0], org[4][1], pv)
        model[(1, 0)] = org[1][0] + k - proj(org[1][0], org[1][1], pv)
    _assert_fast(r, prog, right, wrong)


def check_pv_twilight_readout(r, prog):
    """A twilight point placed at (a, b) is read with GC under the fast vector and copied onto a
    glyph point under an exact axis: the readout is the projection itself."""
    pv = _pv_of(prog)
    axis = _pv_axis(pv)
    toks = prog["text"].split()
    a, b = int(toks[toks.index("SCFS") - 1]), int(toks[toks.index("SCFS", toks.index("SCFS") + 1) - 1])
    into = int(toks[len(toks) - 3])
    right = {(into, axis): fast(a, b, pv)}
    wrong = {(into, axis): general(a, b, pv)}
    _assert_fast(r, prog, right, wrong)


def check_pv_round_flip(r, prog):
    """MDAP[1] on twilight 1 at (31, 3000) under the fast PV, FV x, then GC[0] of it and SCFS onto
    11, both still under that PV: 31 rounds to 0, the general 44 to 64."""
    pv = _pv_of(prog)
    assert _pv_axis(pv) == 0
    org = _org_at(12)
    right, wrong = {}, {}
    for model, proj in ((right, fast), (wrong, general)):
        d = proj(31, 3000, pv)
        cx = 31 + rtg(d) - d
        k = proj(cx, 3000, pv)
        model[(11, 0)] = org[11][0] + k - proj(org[11][0], org[11][1], pv)
    assert right[(11, 0)] == 0 and rtg(general(31, 3000, pv)) == 64, "pv_round_flip: the pixel does not flip"
    _assert_fast(r, prog, right, wrong)


def check_dv_sdpvtl(r, prog):
    """SDPVTL[0] 4 3 on twilight org (236, 1) - (0, 0): the dual normalises to the fast vector; MD[1]
    (original, in twilight: org - org under the dual) and GC[1] of 5 at (100, 3000) are 100."""
    dv = normalize(236, 1)[:2]
    assert _pv_axis(dv) == 0
    right = {(8, 0): fast(100, 3000, dv), (9, 0): fast(100, 3000, dv)}
    wrong = {(8, 0): general(100, 3000, dv), (9, 0): general(100, 3000, dv)}
    _assert_fast(r, prog, right, wrong)


def check_fv_sfvtl(r, prog):
    """SFVTL[0] 2 0 at 18 ppem: FV (0x4000, non-zero) selects the X-only move; the general move
    vector (fv * 0x10000 / F.P, F.P = 0x4000) would have shifted y by mulfix(d, fvy * 4)."""
    org = _org_at(18)
    fv = normalize(org[2][0] - org[0][0], org[2][1] - org[0][1])[:2]
    assert fv[0] == 0x4000 and fv[1] != 0, "fv_sfvtl: FV is %s" % (fv,)
    d = 800 - (org[9][0] - org[0][0])
    assert r["points"][9][0] == org[9][0] + d, "fv_sfvtl: x"
    assert mulfix(d, fv[1] * 4) != 0, "fv_sfvtl: the general move would not have moved y either"
    assert r["points"][9][1] == org[9][1] and r["tags"][9] == r["raw"][1][9] | 0x08, "fv_sfvtl: y moved or touched"


def check_swidth_negative(r, prog):
    """SSW -200 (-150) inside the window: the points inside land at rp0 = 0 plus -150, not +150;
    on the MDRP row 9's original distance (151) is outside the window and it stays put."""
    org, orus, s = _org_at(12), _orus(), scale_for(12)
    swv = mulfix(-200, s)
    assert swv == -150, swv
    inside = (8, 9) if "MIRP" in prog["text"] else (8,)
    for p in inside:
        assert r["points"][p][0] == org[0][0] + swv, "%s: point %d at %d" % (prog["name"], p, r["points"][p][0])
        assert r["points"][p][0] != org[0][0] - swv, "%s: point %d took the flipped sign" % (prog["name"], p)
    if 9 not in inside:
        assert abs(mulfix(orus[9][0] - orus[0][0], s) - swv) >= 250 and r["points"][9] == r["raw"][0][9], "%s: 9" % prog["name"]


def check_mdrp_swidth_below(r, prog):
    org, orus, s = _org_at(12), _orus(), scale_for(12)
    od = mulfix(orus[4][0] - orus[3][0], s)
    swv = mulfix(4, s)
    assert od < 0 and abs(od - swv) < 10, "mdrp_swidth_below: org_dist %d is outside the window" % od
    assert r["points"][4][0] == org[3][0] - swv, "mdrp_swidth_below: point 4 at %d" % r["points"][4][0]
    assert r["points"][4][0] != org[3][0] + swv, "mdrp_swidth_below: the positive branch agrees"


def check_mirp_swidth_below(r, prog):
    org, s = _org_at(12), scale_for(12)
    cvt, swv = mulfix(CVT[4], s), mulfix(100, s)
    assert cvt < 0 and abs(cvt - swv) < 200, "mirp_swidth_below: cvt %d is outside the window" % cvt
    assert r["points"][9][0] == org[4][0] - swv, "mirp_swidth_below: point 9 at %d" % r["points"][9][0]
    assert r["points"][9][0] != org[4][0] + swv, "mirp_swidth_below: the positive branch agrees"


def check_swidth_strict(r, prog):
    org, orus, s = _org_at(12), _orus(), scale_for(12)
    swv, cvt7 = mulfix(200, s), mulfix(CVT[7], s)
    d9, d11 = mulfix(orus[9][0] - orus[0][0], s), mulfix(orus[11][0] - orus[0][0], s)
    assert abs(d9 - swv) == 1 and abs(d11 - swv) == 1 and abs(cvt7 - swv) == 2, (d9, d11, cvt7, swv)
    assert r["points"][9][0] == org[0][0] + cvt7 and r["points"][13][0] == org[0][0] + cvt7, "swidth_strict: MIRP"
    assert r["points"][11][0] == org[0][0] + swv, "swidth_strict: 11 did not snap under SSWCI 2"
    assert r["points"][9][0] != org[0][0] + swv, "swidth_strict: a <= window would have snapped 9"


def check_round_states(r, prog):
    """Every MDRP[00100] here lands somewhere RTG would not have put it."""
    org, orus, s = _org_at(12), _orus(), scale_for(12)
    toks = prog["text"].split()
    ref, groups, cur = 0, [], []
    for k, t in enumerate(toks):
        if t == "SRP0":
            ref = int(toks[k - 1])
        if t in ("SROUND", "S45ROUND", "RDTG", "RUTG", "RTDG") and cur:
            groups.append(cur)
            cur = []
        if t == "MDRP[00100]":
            cur.append((ref, int(toks[k - 1])))
    groups.append(cur)
    for g in groups:
        for ref, p in g:
            d = mulfix(orus[p][0] - orus[ref][0], s)
            assert r["points"][p][0] != org[ref][0] + rtg(d), "%s: %d from %d (%d) rounds like RTG" % (prog["name"], p, ref, d)


def check_zero_orgdist(r, prog):
    org, s = _org_at(12), scale_for(12)
    cvt0 = mulfix(CVT[0], s)
    assert cvt0 < 0
    assert r["points"][9][0] == org[9][0] + 64, "zero_orgdist: 9 was not lifted to the minimum distance"
    assert r["points"][11][0] == org[11][0] - cvt0, "zero_orgdist: 11 did not auto-flip a negative cvt on 0"
    assert r["points"][13][0] == org[13][0] + cvt0, "zero_orgdist: 13 flipped under FLIPOFF"


def check_mdrp_twilight_target(r, prog):
    """org - org (100 - org2.x) rounded, not orus - orus ((0 - 207) * 0.75)."""
    org, orus, s = _org_at(12), _orus(), scale_for(12)
    cd = 100 - org[2][0]
    right = 100 + rtg(cd) - cd
    wrong = 100 + rtg(mulfix(0 - orus[2][0], s)) - cd
    assert right != wrong
    assert r["points"][13][0] == right and r["points"][12][0] == 100, "mdrp_twilight_target: cur %d org %d" % (
        r["points"][13][0], r["points"][12][0])


def check_msirp_twilight_diag_pv(r, prog):
    org = _org_at(12)
    assert r["points"][11][1] != org[2][1] and r["points"][13][0] != org[2][0], "diag_pv: 3's original moved on one axis only"
    assert r["points"][10][1] == org[2][1] and r["points"][12][0] != org[2][0], "diag_pv: X-only moved 4's org.y"
    fv = normalize(236, 1)[:2]
    assert mulfix(r["points"][12][0] - org[2][0], fv[1] * 4) != 0, "diag_pv: the general path would not have moved y"


def check_msirp_twilight_antiparallel(r, prog):
    org = _org_at(12)
    assert r["points"][13][0] == org[2][0] + 100, "antiparallel: org.x is %d" % r["points"][13][0]
    assert r["points"][13][0] != org[2][0] - 100


def check_msirp_twilight_diag(r, prog):
    org = _org_at(12)
    fv = normalize(3, 4)[:2]
    mvy = int((fv[1] * 0x10000) / fv[0])
    assert r["points"][13][0] == org[2][0] + 100 and r["points"][12][1] == org[2][1] + mulfix(100, mvy), \
        "msirp_twilight_diag: (%d, %d)" % (r["points"][13][0], r["points"][12][1])
    assert r["points"][12][1] != org[2][1], "msirp_twilight_diag: y did not move (the X-only reading)"


def check_msirp_twilight_yfast(r, prog):
    org = _org_at(12)
    assert r["points"][13][1] == org[2][1] + 100 and r["points"][13][1] != org[2][1], "msirp_twilight_yfast"


def check_miap_twilight_perp(r, prog):
    cvt = mulfix(CVT[10], scale_for(12))
    got = ((r["points"][12][0], r["points"][10][1]), (r["points"][13][0], r["points"][11][1]))
    assert got == ((0, cvt), (0, cvt)), "miap_twilight_perp: %s" % (got,)
    assert got[0] != (cvt, 0), "miap_twilight_perp: org was written along the projection"


def check_mirp_cutin_gate(r, prog):
    org, s = _org_at(12), scale_for(12)
    cvt = mulfix(CVT[8], s)
    assert abs(cvt - (org[9][0] - 100)) > 68, "cutin_gate: 9 is within the cut-in of cvt 8"
    assert r["points"][9][0] == 100 + rtg(cvt), "cutin_gate: 9 at %d" % r["points"][9][0]
    assert r["points"][9][0] != 100 + rtg(org[9][0] - 100), "cutin_gate: 9 took the cut-in across zones"
    assert r["points"][13][0] == 100 + cvt + rtg(cvt) - cvt, "cutin_gate: twilight 1 at %d" % r["points"][13][0]
    assert r["points"][11][0] == 100 + cvt, "cutin_gate: MIRP[00000] cut in"


def check_sxvtl_zones(r, prog):
    """The deeper operand from zp1 (twilight 0 at (0, 200)), the top from zp2 (glyph 4); swapping the
    zones would read glyph 0 and twilight 4 (at the origin) instead."""
    org = _org_at(12)
    right = normalize(0 - org[4][0], 200 - org[4][1])
    wrong = normalize(org[0][0], org[0][1])
    if "SDPVTL[1]" in prog["text"]:
        right, wrong = (0 - right[1], right[0]), (0 - wrong[1], wrong[0])
        got = (r["points"][11][0], r["points"][10][0])  # GPV leaves y on top: the first SCFS takes it
    else:
        got = (r["points"][13][0], r["points"][12][0])
    assert got == right[:2], "%s: GPV %s, the port says %s" % (prog["name"], got, right[:2])
    assert got != wrong[:2], "%s: the swapped zones agree" % prog["name"]


def check_spvfs_zero(r, prog):
    org = _org_at(12)
    assert (r["points"][13][0], r["points"][12][0]) == (0, 0x4000), "spvfs_zero: PV changed"
    assert r["points"][6][1] == rtg(org[6][1]) and r["points"][6][0] == org[6][0], "spvfs_zero: MDAP did not round y"
