def check_idef_standard(r, prog):
    assert r["points"][13][0] == 3, "idef_standard: 13 at %d" % r["points"][13][0]
    assert r["points"][1] == r["raw"][0][1], "idef_standard: the IDEF body ran on point 1"
    base = hint_once(r["code"], prog["ppem"], 0)
    assert base["points"] == r["points"], "idef_standard: font 0 answers differently, so the IDEF was reached"


def check_fpgm_getinfo(r, prog):
    org = _org_at(12)
    assert r["points"][13][0] == org[13][0] + 64 and r["points"][13][0] != org[13][0] + 128, "fpgm_getinfo: fn 9"
    assert r["points"][12][0] == 0x1000, "fpgm_getinfo: GETINFO 32 at glyph time is %d" % r["points"][12][0]
    check_font_differs(r, prog)


# --- round 4 --------------------------------------------------------------------------------------
def _component(r, prog):
    """The hinted glyph 1 of the row's font under the row's glyph-1 program: what every component
    of the composite looked like before placement (its pp1 is 0 on every composite font)."""
    return hint_once(r["code"], prog["ppem"], prog["font"], 1)


def _pair(r, prog):
    c = _component(r, prog)
    return c["points"], c["tags"]


def check_comp_offset_round(r, prog):
    pts, tags = _pair(r, prog)
    assert r["n"] == 28, r["n"]
    for i in range(NPTS):
        assert r["points"][i] == pts[i], "comp_offset_round: component 0 point %d moved" % i
        assert r["points"][14 + i] == (pts[i][0], pts[i][1] - 64), "comp_offset_round: point %d" % (14 + i)
        assert r["points"][14 + i][1] != pts[i][1] - 128 and r["points"][14 + i][1] != pts[i][1] - 96
        assert r["tags"][i] & 0x18 == 0, "comp_offset_round: touch bits survived on %d" % i
    assert tags[6] & 0x10, "comp_offset_round: the component program did not touch 6"
    assert r["tags"][0] & 4 and r["tags"][14] & 4, "comp_offset_round: scan bits on the first points"
    assert r["advance"] == 896, r["advance"]


def check_comp_offset_unrounded(r, prog):
    pts, tags = _pair(r, prog)
    assert r["n"] == 28
    for i in range(NPTS):
        assert r["points"][14 + i] == (pts[i][0], pts[i][1] - 96), "comp_offset_unrounded: point %d" % (14 + i)


def _scaled_points(pts, m):
    """FT_Vector_Transform on F26Dot6 points with a 16.16 matrix from F2Dot14 * 4 (file order
    xscale, scale01, scale10, yscale -> FreeType xx, yx, xy, yy), each term FT_MulFix."""
    xx, yx, xy, yy = [v * 4 for v in matrix4(m)]
    return [(mulfix(x, xx) + mulfix(y, xy), mulfix(x, yx) + mulfix(y, yy)) for x, y in pts]


def _check_scaled(r, prog, off, wrong):
    pts, tags = _pair(r, prog)
    m = FONTS[prog["font"]]["glyph2"]["records"][1][4]
    want = _scaled_points(pts, m)
    for i in range(NPTS):
        assert r["points"][i] == pts[i], "%s: component 0 point %d moved" % (prog["name"], i)
        got = r["points"][14 + i]
        assert got == (want[i][0] + off[0], want[i][1] + off[1]), "%s: point %d %s" % (prog["name"], 14 + i, got)
        assert got != (want[i][0] + wrong[0], want[i][1] + wrong[1])


def check_comp_scale_scaled(r, prog):
    _check_scaled(r, prog, (128, 64), (320, 128))


def check_comp_scale_unscaled(r, prog):
    _check_scaled(r, prog, (320, 128), (128, 64))


def check_comp_scale_neither(r, prog):
    """The measurement the header quotes: neither flag -> the default build scales nothing."""
    _check_scaled(r, prog, (320, 128), (128, 64))


def check_comp_2x2_shear(r, prog):
    pts, tags = _pair(r, prog)
    m = FONTS[prog["font"]]["glyph2"]["records"][1][4]
    want = _scaled_points(pts, m)
    single = [((x * 0x8000 + 0x8000) >> 16, (x * 0x4000 + y * 0x8000 + 0x8000) >> 16) for x, y in pts]
    differs = 0
    for i in range(NPTS):
        got = r["points"][14 + i]
        assert got == (want[i][0] + 320, want[i][1] + 128), "comp_2x2_shear: point %d %s" % (14 + i, got)
        if got != (single[i][0] + 320, single[i][1] + 128):
            differs += 1
    assert differs > 0, "comp_2x2_shear: per-term and single rounding agree on every point"


def check_comp_point_match(r, prog):
    pts, tags = _pair(r, prog)
    org = _org()
    assert pts[2][0] != org[2][0], "comp_point_match: the program did not move point 2"
    assert pts[2][0] % 64 != 0, "comp_point_match: point 2 is on the grid, the offset would be whole"
    assert r["points"][14 + 9] == r["points"][2] == pts[2], "comp_point_match: 9' is not on 2"
    for i in range(NPTS):
        d = (pts[2][0] - pts[9][0], pts[2][1] - pts[9][1])
        assert r["points"][14 + i] == (pts[i][0] + d[0], pts[i][1] + d[1]), "comp_point_match: point %d" % (14 + i)
    assert r["points"][14 + 9][0] != org[2][0], "comp_point_match: the org reading gives the same offset"


def check_comp_use_my_metrics(r, prog):
    assert r["advance"] == 512, "comp_use_my_metrics: advance %d" % r["advance"]
    assert r["advance"] != 704 and r["advance"] != 448


def check_comp_program_shc_mdrp(r, prog):
    pts, _ = _pair(r, prog)
    assert r["code"] == b""
    p0 = pts[0][0]
    assert p0 % 64 != 0, "comp_program_shc_mdrp: point 0 is on the grid, MDAP[1] would not move it"
    disp = rtg(p0) - p0
    assert r["points"][0][0] == rtg(p0)
    for i in range(1, 8):
        assert r["points"][i][0] == pts[i][0] + disp, "comp_program_shc_mdrp: SHC did not shift %d" % i
    for i in range(8, NPTS):
        assert r["points"][i][0] == pts[i][0], "comp_program_shc_mdrp: contour 1 moved"
    dist = (pts[3][0] + 448) - p0  # orus == cur at the start of the composite run
    right = rtg(p0) + rtg(dist)
    wrong = rtg(p0) + rtg(mulfix(dist, scale_for(12)))
    assert right != wrong, "comp_program_shc_mdrp: pick a distance the two scales round apart"
    assert r["points"][17][0] == right, "comp_program_shc_mdrp: 17 at %d, want %d" % (r["points"][17][0], right)


def check_comp_noprog(r, prog):
    pts, tags = _pair(r, prog)
    for i in range(NPTS):
        assert r["points"][i] == (pts[i][0] - 30, pts[i][1]), "comp_noprog: point %d not translated by -30" % i
        assert r["points"][i][0] != pts[i][0] - 32
        assert r["tags"][i] == tags[i] and r["tags"][14 + i] == tags[i], "comp_noprog: tags differ at %d" % i
    assert tags[2] & 8 and tags[6] & 16, "comp_noprog: the component program touched nothing"
    assert r["advance"] == 896, r["advance"]


def check_comp_instr0(r, prog):
    twin = hint_once(r["code"], prog["ppem"], _F("c_noinstr"), 2)
    assert (r["points"], r["tags"], r["advance"]) == (twin["points"], twin["tags"], twin["advance"]), \
        "comp_instr0: WE_HAVE_INSTR with n_ins 0 differs from no WE_HAVE_INSTR"


def check_comp_nested(r, prog):
    pts, tags = _pair(r, prog)
    assert r["n"] == 42
    for i in range(NPTS):
        assert r["points"][i] == (pts[i][0] - 64, pts[i][1]), "comp_nested: glyph 1 component point %d" % i
    base2 = [(x, y + 384) for x, y in pts] + [(x + 448, y + 384) for x, y in pts]  # glyph 2 placed
    for j in range(8, 28):  # sub-zone points 8..27: IUP left contour 1 and the second copy alone;
        got = r["points"][14 + j]  # SHPIX moved 13 by 64 and SHZ every other point by the same 64,
        want = base2[j]  # then the translation by -pp1.x (shifted to 64 too) took the 64 back
        assert got == want, "comp_nested: sub-zone point %d %s, want %s" % (j, got, want)
    for j in (1, 2, 5, 6, 7):  # between the touched 0 (+32) and 4 (0) in x order; 3 lies past 4
        assert r["points"][14 + j] != base2[j], "comp_nested: IUP did not move %d" % j
    assert r["points"][14][0] == base2[0][0] + 32, "comp_nested: point 0 of the sub-zone"
    assert r["advance"] == 896, r["advance"]


def check_comp_empty(r, prog):
    pts, tags = _pair(r, prog)
    assert r["n"] == NPTS
    for i in range(NPTS):
        assert r["points"][i] == pts[i], "comp_empty: point %d" % i
    assert r["advance"] == 896, r["advance"]


def check_pp1_readout(r, prog):
    org = _org()
    assert r["points"][0][0] == 0, "pp1_readout: point 0 x is %d" % r["points"][0][0]
    for i in range(1, NPTS):
        assert r["points"][i][0] == org[i][0] - 64, "pp1_readout: point %d" % i
    assert r["advance"] == 448, r["advance"]


def check_pp1_moved(r, prog):
    org = _org()
    for i in range(NPTS):
        assert r["points"][i][0] == org[i][0] - 128, "pp1_moved: point %d" % i
    assert r["advance"] == 384, r["advance"]


def check_pp4_floor(r, prog):
    assert r["points"][0][1] == 37, "pp4_floor: point 0 y is %d" % r["points"][0][1]
    assert r["points"][0][1] != -27


def check_vmtx(r, prog):
    assert (r["points"][0][1], r["points"][1][1]) == (512, -384), "vmtx: %s" % (r["points"][:2],)
    base = hint_once(r["code"], prog["ppem"], 0)
