# --- round 5 ---------------------------------------------------------------------------------------
def check_div_trunc(r, prog):
    assert (r["points"][12][0], r["points"][13][0]) == (46, -46), (r["points"][12], r["points"][13])
    assert (muldiv(93, 64, 128), muldiv(93, 64, -128)) == (47, -47)  # the rounding DIV, ruled out


def check_mul_round(r, prog):
    assert (r["points"][12][0], r["points"][13][0]) == (64, -64), (r["points"][12], r["points"][13])
    assert (93 * 44) // 64 == 63 and -((93 * 44) // 64) == -63  # the truncating MUL, ruled out


def _hypot16(a, b):
    """A float model of FT_Hypot on 16.16 values, for the non-degeneracy checks only (FreeType's
    CORDIC is within a unit or two of it)."""
    return int(round(math.hypot(a, b)))


def _scaled_offset(m, off, ppem, rnd):
    """The model of a SCALED_COMPONENT_OFFSET: FT_MulFix by FT_Hypot of the matrix column, then
    the size, then FT_PIX_ROUND when the record rounds."""
    xx, yx, xy, yy = [v * 4 for v in matrix4(m)]
    x = mulfix(off[0], _hypot16(xx, xy))
    y = mulfix(off[1], _hypot16(yy, yx))
    x, y = mulfix(x, scale_for(ppem)), mulfix(y, scale_for(ppem))
    return (pix_round(x), pix_round(y)) if rnd else (x, y)


def _transposed_offset(m, off, ppem, rnd):
    """The wrong pairing: x by hypot(xx, yx), y by hypot(yy, xy)."""
    xx, yx, xy, yy = [v * 4 for v in matrix4(m)]
    x = mulfix(off[0], _hypot16(xx, yx))
    y = mulfix(off[1], _hypot16(yy, xy))
    x, y = mulfix(x, scale_for(ppem)), mulfix(y, scale_for(ppem))
    return (pix_round(x), pix_round(y)) if rnd else (x, y)


def _measured_offset(r, prog):
    """The translation FreeType applied to the second component: got - transformed, the same on
    every point (asserted), with component 0 untouched."""
    pts, tags = _pair(r, prog)
    m = FONTS[prog["font"]]["glyph2"]["records"][1][4]
    want = _scaled_points(pts, m)
    offs = set()
    for i in range(NPTS):
        assert r["points"][i] == pts[i], "%s: component 0 point %d moved" % (prog["name"], i)
        got = r["points"][14 + i]
        offs.add((got[0] - want[i][0], got[1] - want[i][1]))
    assert len(offs) == 1, "%s: the offset is not a translation: %s" % (prog["name"], sorted(offs))
    return offs.pop()


def _check_cordic_offset(r, prog, want, wrong, rnd, tol=2):
    off = _measured_offset(r, prog)
    rec = FONTS[prog["font"]]["glyph2"]["records"][1]
    model = _scaled_offset(rec[4], (rec[2], rec[3]), prog["ppem"], rnd)
    assert off == want, "%s: offset %s, expected %s" % (prog["name"], off, want)
    assert abs(off[0] - model[0]) <= tol and abs(off[1] - model[1]) <= tol, (prog["name"], off, model)
    for w in wrong:
        assert off != w, "%s: the wrong reading %s agrees" % (prog["name"], w)
    return off


def check_comp_shear_scaled(r, prog):
    rec = FONTS[prog["font"]]["glyph2"]["records"][1]
    t = _transposed_offset(rec[4], (rec[2], rec[3]), 12, True)
    assert t == (192, 64), t
    _check_cordic_offset(r, prog, (128, 64), [t, (320, 128)], True)


def check_comp_shear_scaled_noround(r, prog):
    rec = FONTS[prog["font"]]["glyph2"]["records"][1]
    t = _transposed_offset(rec[4], (rec[2], rec[3]), 12, False)
    assert t == (168, 75), t
    off = _check_cordic_offset(r, prog, (150, 84), [t, (300, 150)], False)
    assert off[1] % 64 != 0, "comp_shear_scaled_noround: y landed on the grid"


def check_comp_rot_scaled(r, prog):
    rec = FONTS[prog["font"]]["glyph2"]["records"][1]
    t = _transposed_offset(rec[4], (rec[2], rec[3]), 12, False)
    assert t == (-167, 122), t
    _check_cordic_offset(r, prog, (-158, 126), [t, (-250, 133)], False)


def check_comp_rot_scaled_round(r, prog):
    _check_cordic_offset(r, prog, (-128, 128), [(-256, 128)], True)


def check_comp_scale1_scaled(r, prog):
    _check_cordic_offset(r, prog, (-170, 56), [(-226, 74)], False)


def check_comp_xyscale_scaled(r, prog):
    pts, _ = _pair(r, prog)
    off = _check_cordic_offset(r, prog, (150, 113), [(300, 150), (150, 75)], False)
    half = [(mulfix(x, 0x8000), mulfix(y, 0x8000)) for x, y in pts]  # the x scale on both axes
    differs = sum(1 for i in range(NPTS) if r["points"][14 + i] != (half[i][0] + off[0], half[i][1] + off[1]))
    assert differs > 0, "comp_xyscale_scaled: a uniform 0.5 gives the same points"


def check_comp_both_flags(r, prog):
    _check_scaled(r, prog, (128, 64), (320, 128))


def check_comp_point_match_bytes(r, prog):
    check_comp_point_match(r, prog)
    pts, _ = _pair(r, prog)
    xy = (mulfix(2, scale_for(12)), mulfix(9, scale_for(12)))
    assert r["points"][14] != (pts[0][0] + xy[0], pts[0][1] + xy[1]), "comp_point_match_bytes: read as an offset"


def check_comp_nested_point_match(r, prog):
    pts, _ = _pair(r, prog)
    assert r["n"] == 42
    assert pts[5][0] % 64 != 0, "comp_nested_point_match: point 5 is on the grid"
    for i in range(NPTS):
        assert r["points"][i] == pts[i], "comp_nested_point_match: base point %d moved" % i
    two = [pts[i] for i in range(NPTS)] + [(pts[i][0] + 448, pts[i][1]) for i in range(NPTS)]  # glyph 2 hinted
    d = (pts[5][0] - two[20][0], pts[5][1] - two[20][1])
    assert d[0] % 64 != 0, "comp_nested_point_match: a whole-pixel offset"
    for j in range(2 * NPTS):
        assert r["points"][14 + j] == (two[j][0] + d[0], two[j][1] + d[1]), "comp_nested_point_match: child %d" % j
    assert r["points"][34] == r["points"][5]
    assert r["points"][14 + 5] != r["points"][5], "comp_nested_point_match: the child's point 5 is on 5 too"
    assert r["advance"] == 896, r["advance"]


def check_comp_empty_umm_program(r, prog):
    pts, _ = _pair(r, prog)
    assert r["n"] == NPTS
    for i in range(NPTS):
        assert r["points"][i] == pts[i], "comp_empty_umm_program: point %d translated" % i
        assert r["points"][i][0] != pts[i][0] - 64
    assert r["advance"] == 384 and r["advance"] != 896, r["advance"]


def check_comp_empty_umm_noprogram(r, prog):
    pts, _ = _pair(r, prog)
    assert r["n"] == NPTS
    for i in range(NPTS):
        assert r["points"][i] == (pts[i][0] + 15, pts[i][1]), "comp_empty_umm_noprogram: point %d" % i
        assert r["points"][i][0] != pts[i][0] - 60
    assert r["advance"] == 384 and r["advance"] != 896, r["advance"]


def check_comp_all_empty_instr(r, prog):
    assert r["n"] == 0
    assert r["advance"] == 896 and r["advance"] != 960, r["advance"]


def check_vmtx_tail_long(r, prog):
    assert (r["points"][0][1], r["points"][1][1]) == (448, -256), r["points"][:2]
    assert (r["points"][0][1], r["points"][1][1]) != (512, -384)


def check_vmtx_tail_short(r, prog):
    assert (r["points"][0][1], r["points"][1][1]) == (512, -192), r["points"][:2]
    assert r["points"][0][1] != 448 and r["points"][1][1] != -448


def check_comp_shared_copy(r, prog):
    pts, _ = _pair(r, prog)
    cvt8 = mulfix(CVT[8], scale_for(12))
    assert cvt8 == 227, cvt8
    want = {"comp_wcvtp_shared_copy": (999, None), "comp_ws_shared_copy": (None, 777), "comp_wcvtf_shared": (300, None),
            "comp_deltac_shared_copy": (291, None), "comp_wcvtp_composite_reads": (999, None)}[prog["name"]]
    fresh = (cvt8, 0)  # what the reader sees of an unwritten copy: cvt 8 scaled, storage 5 zero
    for k in range(2):
        v = fresh[k] if want[k] is None else want[k]
        assert r["points"][14 + k] == (v + 448, pts[k][1]), "%s: point %d %s" % (prog["name"], 14 + k, r["points"][14 + k])
        if want[k] is not None:
            assert want[k] != fresh[k]
    if prog["name"] == "comp_wcvtp_composite_reads":
        assert r["points"][2][0] == 999, r["points"][2]
    else:
        for i in range(NPTS):
            assert r["points"][i] == pts[i], "%s: component 0 point %d moved" % (prog["name"], i)


def check_comp_smd_no_gs_leak(r, prog):
    pts, _ = _pair(r, prog)
    p17 = pts[3][0] + 448
    assert p17 == 825, p17
    right = p17 + rtg(896 - p17)
    assert right == 889 and (896 - p17) < 300, (right, 896 - p17)
    assert r["points"][0][0] == right, r["points"][0]
    assert r["points"][0][0] != p17 + 300
    assert r["advance"] == 896 and r["advance"] != 1152, r["advance"]


def check_comp_nested_shz_low(r, prog):
    pts, _ = _pair(r, prog)
    assert r["n"] == 3 + 2 * NPTS
    tri = [(mulfix(x, scale_for(12)), mulfix(y, scale_for(12))) for x, y, _ in TRIANGLE]
    for i in range(3):
        assert r["points"][i] == (tri[i][0] - 64, tri[i][1]), "comp_nested_shz_low: triangle point %d" % i
    base2 = [(x, y + 384) for x, y in pts] + [(x + 448, y + 384) for x, y in pts]
    for j in range(8, 28):
        assert r["points"][3 + j] == base2[j], "comp_nested_shz_low: sub-zone point %d" % j
    for j in (1, 2, 5, 6, 7):
        assert r["points"][3 + j] != base2[j], "comp_nested_shz_low: IUP did not move %d" % j
    assert r["points"][3][0] == base2[0][0] + 32
    assert r["advance"] == 896, r["advance"]


