def run_check(prog, r):
    if not prog["check"]:
        return
    fn = CHECKS[prog["check"]]
    if fn.__code__.co_argcount == 2:
        fn(r, prog)
    else:
        fn(r)


def run_all():
    out = []
    for prog in PROGRAMS:
        r = run_program(prog)
        run_check(prog, r)
        out.append(r)
    return out


# ----------------------------------------------------------------------------------------------
# The Cyrius module
# ----------------------------------------------------------------------------------------------
CHUNK = 20  # bytes per string literal: 4 characters each keeps the line under 120 bytes

# cyrlint's deferral markers (design A14): the first five exact-case, the rest case-folded. The
# emitted module must contain none of them, in code or in a comment.
DEFERRAL_EXACT = ("NOT_IMPLEMENTED", "SCAFFOLD", "TODO", "FIXME", "XXX")
DEFERRAL_FOLDED = ("deferred", "follow-up", "for now", "not yet", "later bite", "future bite", "out of scope")


def _lit(b):
    return '"' + "".join("\\x%02x" % c for c in b) + '"'


def _wrap(prefix, text, width=110):
    """Comment lines: `prefix` then the words of `text`, wrapped so no line passes `width` bytes;
    continuation lines start with `#  `."""
    lines, cur, sep = [], prefix, "" if prefix.endswith(" ") else " "
    for w in text.split():
        if len((cur + sep + w).encode()) > width and cur != prefix:
            lines.append(cur)
            cur, sep = "#   " + w, " "
        else:
            cur, sep = cur + sep + w, " "
    lines.append(cur)
    return lines


def _chunks_fn(name, data):
    out = ["fn %s(k): i64 {" % name]
    for k in range(0, len(data), CHUNK):
        out.append("    if (k == %d) { return %s; }" % (k // CHUNK, _lit(data[k : k + CHUNK])))
    out += ["    return 0;", "}", ""]
    return out


def _record(rec):
    """A consumer-flow record as decimal text: `points contours advance end.. x y tag..`, or the
    single -1 for a glyph not recorded."""
    if rec is None:
        return "-1"
    points, tags, ends, adv = rec
    nums = [len(points), len(ends), adv] + list(ends)
    for (x, y), t in zip(points, tags):
        nums += [x, y, t]
    return " ".join(str(v) for v in nums)


TEXT_CHUNK = 86  # characters of decimal text per literal: the line stays under 120 bytes


def _text_chunks_fn(name, text):
    """Like _chunks_fn, for a space-separated decimal text: whole numbers per literal, never a
    number split across two, so a chunk boundary reads as a separator."""
    out = ["fn %s(k): i64 {" % name]
    words, k, cur = text.split(), 0, ""
    for w in words:
        if cur and len(cur) + 1 + len(w) > TEXT_CHUNK:
            out.append('    if (k == %d) { return "%s"; }' % (k, cur))
            k, cur = k + 1, w
        else:
            cur = (cur + " " + w) if cur else w
    out.append('    if (k == %d) { return "%s"; }' % (k, cur))
    out += ["    return 0;", "}", ""]
    return out


def _pairs(lines, items, per=2):
    """`per` items to a line, fewer when that would pass 120 bytes (a long program name)."""
    row = []
    for it in items:
        if row and (len(row) == per or len(("    " + "  ".join(row + [it])).encode()) > 120):
            lines.append("    " + "  ".join(row))
            row = []
        row.append(it)
    if row:
        lines.append("    " + "  ".join(row))


def module_lines(results):
    """The module's text as a list of lines, from FreeType's results."""
    fonts = [base_font(f) for f in range(len(FONTS))]
    outs = outlines_of(0)
    ver = ftshim.version_string()
    n = len(PROGRAMS)
    n_comp = sum(1 for p in PROGRAMS if p["gid"] != 1)
    n_g4 = sum(1 for f in FONTS if f["glyph4"] is not None)
    tables = " ".join(sorted(["cmap", "cvt", "fpgm", "glyf", "head", "hhea", "hmtx", "loca", "maxp", "post", "prep"]))
    L = []
    L += [
        "# programs/hint_unit_vectors.cyr — GENERATED by scripts/hint_unit_vectors.py from FreeType %s" % ver,
        "# (classic interpreter, GETINFO version 35, grayscale, FT_LOAD_NO_AUTOHINT). DO NOT EDIT.",
        "#",
        "# A synthetic TrueType font — glyph 1 a simple glyph of two contours, %d points; glyph 2 a" % NPTS,
        "# COMPOSITE of two glyph-1 components; glyph 3 a composite of glyph 1 then glyph 2 (nested);",
        "# glyph 0 empty; on %d variants a glyph 4 with an outline and a program of its own; a 16-entry" % n_g4,
        "# cvt, a two-function fpgm — in %d VARIANTS that differ from font 0 (prep RTG) in their prep," % len(FONTS),
        "# their fpgm, one maxp field, their composite records, an hmtx entry, hhea.descender, a vmtx",
        "# or a glyph 4 (each says which below), and %d glyph PROGRAMS run through FreeType itself at" % n,
        "# their ppem on their font. For each program: the bytes, the glyph FreeType loaded, and what",
        "# its glyph slot held afterwards — every outline point's hinted position (F26Dot6), its tag",
        "# byte, and the advance. Every program was ALSO loaded under FT_LOAD_PEDANTIC on a fresh face",
        "# and loaded clean, so no instruction was skipped silently. And for EVERY row, glyphs 1, 2 and",
        "# 3 of its font were loaded in that order on ONE face at the row's ppem — the consumer's",
        "# flow, `prep` once — and glyph 2's and 3's outlines recorded (hu_expect2_*, hu_expect3_*),",
        "# confirmed equal on a second fresh face under FT_LOAD_PEDANTIC. Nothing here was computed",
        "# by rekha or by a second hand-written interpreter.",
        "#",
        "# ⛔ NOT REGENERATED IN CI. CI's Ubuntu ships FreeType 2.13.2, whose move arithmetic (the",
        "# fv * 0x10000 / F_dot_P quotient), ODD/EVEN test, stack margin and DELTAP pop discipline differ",
        "# from the 2.14.3 rekha targets; `fv_b1_regime` below is a move the two versions disagree on.",
        "# Regenerate by hand on a 2.14.x host with",
        "#   python3 scripts/hint_unit_vectors.py emit programs/hint_unit_vectors.cyr",
        "# and review the diff like any other transcription. The emitter lints and formats its output",
        "# before writing it, so this file is gate-clean by construction.",
        "#",
        "# Rules a consumer needs (each measured on FreeType, not read from a spec):",
        "#   * hu_expect_x(p, i) is FreeType's REPORTED x of outline point i: the interpreter's cur.x MINUS",
        "#     cur[pp1].x, because TT_Load_Glyph translates the hinted outline so that pp1 is the origin",
        "#     (ref2143/ttgload.c:2578-2583); hu_expect_y is cur.y as it is. On font 0 lsb == xMin and no",
        "#     program moves pp1, so the subtraction is of 0; `pp1_offset_readout`, `pp1_moved`,",
        "#     `comp_noprog_touch_bits` and `comp_nested_first_point` are the rows where it is not.",
        "#   * hu_expect_tag(p, i) is the tag byte: 1 on-curve, 8 touched in x, 16 touched in y, and on",
        "#     point 0 ALSO 4 (FT_CURVE_TAG_HAS_SCANMODE) with scan_type << 5, which TT_Hint_Glyph sets",
        "#     after any glyph program ran (ref2143/ttgload.c:839-840) — inside a composite, on the first",
        "#     point of every component whose program ran. Mask with 0x19 (25) for the interpreter's",
        "#     bits: 1 -> ONCURVE, 8 -> TOUCHX, 16 -> TOUCHY.",
        "#   * hu_expect_advance(p) is slot->advance.x: pp2.x - pp1.x after the base layer's grid fit,",
        "#     equal to ((cur[pp2].x - cur[pp1].x) + 32) & -64 (FT_PIX_ROUND's floor form), which is",
        "#     cur[pp2].x - cur[pp1].x whenever both phantoms sit on the grid.",
        "#   * hu_phantom_x/y(g, k) are pp1..pp4 of glyph g OF FONT 0 in FONT UNITS before scaling, per",
        "#     tt_loader_set_pp (ref2143/ttgload.c:1336-1347) for a font with NO `vmtx` and NO `OS/2`:",
        "#     pp1 = (xMin - lsb, 0) = (0, 0) because lsb == xMin, pp2 = (pp1.x + advanceWidth, 0), and",
        "#     TT_Get_VMetrics (ttgload.c:112-138) gives tsb = hhea.ascender - yMax and ah = |ascender -",
        "#     descender|, so pp3 = (0, yMax + tsb) = (0, ascender) and pp4 = (0, pp3.y - ah) =",
        "#     (0, descender). The loader then scales all four and rounds pp1.x, pp2.x, pp3.y, pp4.y in",
        "#     cur only, with FT_PIX_ROUND (`phantoms` reads back cur 0/448/576/-128 and org 450/600/-150",
        "#     at 12 ppem; `phantom_pp4_floor` reads -160 -> -128; `phantom_vmtx` the vmtx branch). A",
        "#     variant that changes an hmtx entry, the descender or adds a vmtx says so in its `differs:`",
        "#     line; its phantoms follow the same rule from those values.",
        "#   * a composite row (hu_program_gid(p) is 2 or 3): every component is glyph 1 running the",
        "#     row's glyph-1 program with its OWN phantoms, then transformed by the record's 2x2 on the",
        "#     hinted F26Dot6 points (FT_MulFix per term), translated by the scaled offset (FT_PIX_ROUND",
        "#     when ROUND_XY_TO_GRID; scaled by the matrix first only under SCALED_COMPONENT_OFFSET — a",
        "#     record with neither flag is UNSCALED on this host's build, `comp_scale_neither`) or by",
        "#     the point-matching difference of hinted points (unrounded); with USE_MY_METRICS the",
        "#     composite's phantoms are that component's, un-offset. A composite program (WE_HAVE_INSTR",
        "#     with n_ins > 0) first clears every component point's touch bits, sets org = orus = cur",
        "#     and x_scale = y_scale = 1.0, rounds the phantoms, and runs over the assembled zone",
        "#     (ttgload.c:1178-1249, 777-860); without one (or with n_ins 0) nothing more happens: touch",
        "#     bits survive and the phantoms stay unrounded. In a NESTED composite the inner glyph's",
        "#     program runs on a sub-zone with first_point = its start: IUP and SHC subtract it, SHZ",
        "#     does not (`comp_nested_first_point`, `comp_nested_shz_low`). A SIMPLE component's own",
        "#     program always runs with first_point 0, whatever its base in the composite (every row's",
        "#     hu_expect2/3 numbers say so: glyph 1's program runs at base 0, 14 and 28 there).",
        "#   * hu_expect2_*(p) / hu_expect3_*(p) are FreeType's glyph 2 and glyph 3 of the row's font —",
        "#     glyph 1 carrying the row's program, glyph 2 the row's composite program — loaded the",
        "#     CONSUMER's way: one face, FT_Set_Pixel_Sizes once at the row's ppem, then FT_Load_Glyph",
        "#     1, 2, 3 in that order, so `prep` ran once and the size's cvt, storage and twilight zone",
        "#     carried from load to load as they do in rekha's context. Only the rows marked",
        "#     `carries state` below differ from the same glyph loaded first on a fresh face (a twilight",
        "#     point a DELTAP moved in the gid-1 load is moved again). points/contours/end/x/y/tag/",
        "#     advance mean what the hu_expect_* ones mean; hu_expect2_points(p) = -1 would mark a glyph",
        "#     that FT_LOAD_PEDANTIC refused in the sequence (none does in this file; the row comment",
        "#     would carry the reason).",
        "#   * a font's glyph 4, where `differs:` lists one, is a simple glyph that carries ITS OWN",
        "#     program in the embedded copy (the only glyph that does: it is the font's, not a row's),",
        "#     so a composite naming gid 1 and gid 4 runs two different component programs in one load",
        "#     (`comp_wcvtp_shared_copy` and its siblings read back what glyph 1's program wrote), or",
        "#     a 3-point glyph starts a nested composite (`comp_nested_shz_low`).",
        "#   * twilight points are never in the outline; a program that needs one observed reads it out",
        "#     with GC[0] on zone 0 and SCFS on a glyph point (the `read_twilight` idiom in the script).",
        "#     Every twilight index used is below 16, the font's maxTwilightPoints and FreeType's own",
        "#     per-run bound for this glyph.",
        "#   * a program on font 1..%d runs AFTER that font's fpgm and prep ran (the prep at the program's" % (len(FONTS) - 1),
        "#     ppem); what its expected values show that font 0 would not is the carry-over of that",
        "#     font's prep, fpgm, maxp field, composite records or metrics alone.",
        "#",
        "# Accessors (all null-safe: anything out of range answers 0):",
        "#   hu_ft_version()                  cstring, the FreeType that produced this file",
        "#   hu_font_count()                  %d font variants, f in 0..%d (font 0 first, unchanged)" % (len(FONTS), len(FONTS) - 1),
        "#   hu_font_len(f) / hu_font_copy(f, dst)   font f's bytes; copy writes them at dst, answers len",
        "#   hu_outline_points/contours(g)    glyph g of font 0: %d/%d/%d points (phantoms excluded)," % (len(outs[1][0]), len(outs[2][0]), len(outs[3][0])),
        "#                                    %d/%d/%d contours for g = 1/2/3; g = 0 is empty" % (len(outs[1][1]), len(outs[2][1]), len(outs[3][1])),
        "#   hu_outline_x/y(g, i), hu_outline_on(g, i), hu_contour_end(g, c)   font units; 0/1; last index",
        "#   hu_phantom_x/y(g, k)             k 0..3, font units (see above)",
        "#   hu_program_count/name/ppem/font/gid/points/len(p), hu_program_byte(p, i)    the programs:",
        "#                                    gid is the glyph FreeType loaded, points its outline count",
        "#   hu_expect_x/y/tag(p, i)          hinted cur (see above) and tag of point i < points",
        "#   hu_expect_advance(p)             hinted advance.x",
        "#   hu_expect2_points/contours/advance(p), hu_expect2_end(p, c), hu_expect2_x/y/tag(p, i)",
        "#                                    glyph 2 of the row's font in the consumer flow (see above)",
        "#   hu_expect3_points/contours/advance(p), hu_expect3_end(p, c), hu_expect3_x/y/tag(p, i)",
        "#                                    glyph 3 the same, loaded after glyphs 1 and 2",
        "",
        'fn hu_ft_version(): i64 { return "%s"; }' % ver,
        "",
        "# The fonts: sfnt tables %s (plus vhea + vmtx on `c_vmtx`)." % tables,
        "# maxp of font 0: %d points, %d contours, %d composite points, %d composite contours, 2 zones,"
        % (NPTS, len(CONTOUR_ENDS), len(outs[3][0]), len(outs[3][1])),
        "# %d twilight points, %d storage, %d functions, %d IDEFs, %d stack elements, %d bytes of"
        % (MAX_TWILIGHT, MAX_STORAGE, MAXP_DEFAULT["maxFunctionDefs"], MAXP_DEFAULT["maxInstructionDefs"], MAX_STACK, max_program_len()),
        "# instructions, 2 component elements, depth 2. cvt entry i is i * 101 - 505",
        "# (programs/hint_test.cyr's). fpgm of font 0 defines function 3 (adds 5) and 7 (adds 1):",
        "#   " + " ".join(disasm(fpgm_bytes(0))),
    ]
    L += _wrap("# Glyph 2 of font 0:", records_text(GLYPH2_DEFAULT) + ".")
    L += _wrap("# Glyph 3 of font 0:", records_text(GLYPH3_DEFAULT) + ".")
    L += _wrap("# hmtx of font 0:", ", ".join("glyph %d advance %d lsb %d" % (g, a, l) for g, (a, l) in enumerate(hmtx_of(0))) + ".")
    L += [
        "# Glyphs 1, 2 and 3 carry no program in these copies (a composite keeps its WE_HAVE_INSTR flag",
        "# with n_ins 0 where its variant sets it); a glyph 4 carries its own. Each font's prep",
        "# (`prep:`), and, where a font differs from font 0 in more than its prep, which tables",
        "# (`differs:`) and the fpgm listing:",
    ]
    for f, fd in enumerate(FONTS):
        L += _wrap("#   font %d `%s`, %d bytes:" % (f, fd["name"], len(fonts[f])), fd["why"])
        L += _wrap("#     prep: ", " ".join(disasm(prep_bytes(f))))
        if font_differs(f):
            L += _wrap("#     differs: ", "; ".join(font_differs(f)))
        if fd["fpgm"] is not None:
            L += _wrap("#     fpgm: ", " ".join(disasm(fpgm_bytes(f))))
    L += ["fn hu_font_count(): i64 { return %d; }" % len(FONTS), "", "fn hu_font_len(f): i64 {"]
    _pairs(L, ["if (f == %d) { return %d; }" % (f, len(fonts[f])) for f in range(len(FONTS))], 3)
    L += ["    return 0;", "}", ""]
    for f in range(len(FONTS)):
        L += _chunks_fn("hu_f%d_chunk" % f, fonts[f])
    L.append("fn hu_font_chunk(f, k): i64 {")
    _pairs(L, ["if (f == %d) { return hu_f%d_chunk(k); }" % (f, f) for f in range(len(FONTS))], 2)
    L += [
        "    return 0;",
        "}",
        "",
        "fn hu_font_copy(f, dst): i64 {",
        "    if (dst == 0) { return 0; }",
        "    var n = hu_font_len(f);",
        "    var i = 0;",
        "    while (i < n) {",
        "        store8(dst + i, load8(hu_font_chunk(f, i / %d) + (i %% %d)));" % (CHUNK, CHUNK),
        "        i = i + 1;",
        "    }",
        "    return n;",
        "}",
        "",
        "# The outlines of font 0 in font units: upem %d. Glyph 1: advance %d, lsb %d (= xMin), bbox"
        % (UPEM, ADVANCE, LSB),
        "# %d %d %d %d, hhea ascender %d / descender %d. No coordinate is a multiple of 4, so scale 0.75 rounds"
        % (XMIN, YMIN, XMAX, YMAX, ASCENDER, DESCENDER),
        "# every one of them and orus-scaled distances differ from org distances by 1/64 where it matters.",
        "# Glyph 2 and 3 are their records' assemblies (offsets added, no 2x2 on font 0), lsb = xMin.",
        "fn hu_outline_points(g): i64 {",
    ]
    _pairs(L, ["if (g == %d) { return %d; }" % (g, len(outs[g][0])) for g in (1, 2, 3)], 3)
    L += ["    return 0;", "}", "", "fn hu_outline_contours(g): i64 {"]
    _pairs(L, ["if (g == %d) { return %d; }" % (g, len(outs[g][1])) for g in (1, 2, 3)], 3)
    L += ["    return 0;", "}", ""]
    for fname, col in (("hu_outline_x", 0), ("hu_outline_y", 1), ("hu_outline_on", 2)):
        for g in (1, 2, 3):
            L.append("fn %s_g%d(i): i64 {" % (fname, g))
            _pairs(L, ["if (i == %d) { return %d; }" % (i, pt[col]) for i, pt in enumerate(outs[g][0])], 3)
            L += ["    return 0;", "}", ""]
        L += ["fn %s(g, i): i64 {" % fname]
        _pairs(L, ["if (g == %d) { return %s_g%d(i); }" % (g, fname, g) for g in (1, 2, 3)], 3)
        L += ["    return 0;", "}", ""]
    L.append("fn hu_contour_end(g, c): i64 {")
    items = []
    for g in (1, 2, 3):
        items += ["if (g == %d) { if (c == %d) { return %d; } }" % (g, c, e) for c, e in enumerate(outs[g][1])]
    _pairs(L, items, 2)
    L += ["    return 0;", "}", ""]
    for fname, col in (("hu_phantom_x", 0), ("hu_phantom_y", 1)):
        L.append("fn %s(g, k): i64 {" % fname)
        items = []
        for g in (1, 2, 3):
            pp = phantoms(g)
            items += ["if (g == %d) { if (k == %d) { return %d; } }" % (g, k, pp[k][col]) for k in range(4)]
        _pairs(L, items, 2)
        L += ["    return 0;", "}", ""]
    L += [
        "# The programs. Each hu_c<p>(k) holds glyph 1's bytes in %d-byte literals (hu_k<p>(k) a composite" % CHUNK,
        "# program's, listed as `composite:`); hu_e<p>(i, f) the expected x (f 0), y (f 1) and tag (f 2) of",
        "# outline point i of the glyph FreeType loaded (`gid`). The comment above each is the program's",
        "# purpose and its listing; `font N` names the variant it ran on.",
        "fn hu_pick(f, x, y, t): i64 {",
        "    if (f == 0) { return x; }",
        "    if (f == 1) { return y; }",
        "    return t;",
        "}",
        "",
        "fn hu_program_count(): i64 { return %d; }" % n,
        "",
    ]
    for p, (prog, r) in enumerate(zip(PROGRAMS, results)):
        head = "# %d %s — font %d, gid %d, %d ppem, %d bytes:" % (p, prog["name"], prog["font"], prog["gid"], prog["ppem"], len(r["code"]))
        L += _wrap(head, prog["proves"])
        L += _wrap("#   ", " ".join(disasm(r["code"])) if r["code"] else "(glyph 1 has no program)")
        if r["comp"]:
            L += _wrap("#   composite: ", " ".join(disasm(r["comp"])))
        for g in (2, 3):
            if r["seq"][g] is None:
                L += _wrap("#   glyph %d not recorded: " % g, r["seq_why"][g])
            elif g in r["seq_carries"]:
                L += _wrap("#   glyph %d carries state: " % g, "its numbers differ from the same glyph loaded first "
                           "on a fresh face, because the gid-%s load before it left state the program reads"
                           % ("1" if g == 2 else "1 and gid-2"))
        L += _chunks_fn("hu_c%d" % p, r["code"])
        if r["comp"]:
            L += _chunks_fn("hu_k%d" % p, r["comp"])
        L += _text_chunks_fn("hu_x%d" % p, _record(r["seq"][2]) + " " + _record(r["seq"][3]))
        L.append("fn hu_e%d(i, f): i64 {" % p)
        _pairs(
            L,
            ["if (i == %d) { return hu_pick(f, %d, %d, %d); }" % (i, r["points"][i][0], r["points"][i][1], r["tags"][i])
             for i in range(r["n"])],
            2,
        )
        L += ["    return 0;", "}", ""]
    L.append("fn hu_program_name(p): i64 {")
    _pairs(L, ['if (p == %d) { return "%s"; }' % (p, prog["name"]) for p, prog in enumerate(PROGRAMS)], 2)
    L += ["    return 0;", "}", ""]
    L.append("fn hu_program_ppem(p): i64 {")
    _pairs(L, ["if (p == %d) { return %d; }" % (p, prog["ppem"]) for p, prog in enumerate(PROGRAMS)], 3)
    L += ["    return 0;", "}", ""]
    L.append("fn hu_program_font(p): i64 {")
    _pairs(L, ["if (p == %d) { return %d; }" % (p, prog["font"]) for p, prog in enumerate(PROGRAMS)], 3)
    L += ["    return 0;", "}", ""]
    L.append("# The glyph FreeType loaded for the row: 1 for every row but the %d composite rows (2 or 3)." % n_comp)
    L.append("fn hu_program_gid(p): i64 {")
    _pairs(L, ["if (p == %d) { return %d; }" % (p, prog["gid"]) for p, prog in enumerate(PROGRAMS)], 3)
    L += ["    return 0;", "}", ""]
    L.append("fn hu_program_points(p): i64 {")
    _pairs(L, ["if (p == %d) { return %d; }" % (p, r["n"]) for p, r in enumerate(results)], 3)
    L += ["    return 0;", "}", ""]
    L.append("fn hu_program_len(p): i64 {")
    _pairs(L, ["if (p == %d) { return %d; }" % (p, len(r["code"])) for p, r in enumerate(results)], 3)
    L += ["    return 0;", "}", ""]
    L.append("fn hu_code_chunk(p, k): i64 {")
    _pairs(L, ["if (p == %d) { return hu_c%d(k); }" % (p, p) for p in range(n)], 3)
    L += ["    return 0;", "}", ""]
    L += [
        "fn hu_program_byte(p, i): i64 {",
        "    if (i < 0) { return 0; }",
        "    if (i >= hu_program_len(p)) { return 0; }",
        "    return load8(hu_code_chunk(p, i / %d) + (i %% %d));" % (CHUNK, CHUNK),
        "}",
        "",
        "# A composite row's composite program (glyph 2's; the nested row's glyph 2 inside glyph 3):",
        "# hu_composite_len(p) bytes, hu_composite_byte(p, i). 0 for a row without one.",
        "fn hu_composite_len(p): i64 {",
    ]
    _pairs(L, ["if (p == %d) { return %d; }" % (p, len(r["comp"])) for p, r in enumerate(results) if r["comp"]], 3)
    L += ["    return 0;", "}", "", "fn hu_composite_chunk(p, k): i64 {"]
    _pairs(L, ["if (p == %d) { return hu_k%d(k); }" % (p, p) for p, r in enumerate(results) if r["comp"]], 3)
    L += [
        "    return 0;",
        "}",
        "",
        "fn hu_composite_byte(p, i): i64 {",
        "    if (i < 0) { return 0; }",
        "    if (i >= hu_composite_len(p)) { return 0; }",
        "    return load8(hu_composite_chunk(p, i / %d) + (i %% %d));" % (CHUNK, CHUNK),
        "}",
        "",
        "fn hu_expect(p, i, f): i64 {",
        "    if (i < 0) { return 0; }",
        "    if (i >= hu_program_points(p)) { return 0; }",
    ]
    _pairs(L, ["if (p == %d) { return hu_e%d(i, f); }" % (p, p) for p in range(n)], 3)
    L += [
        "    return 0;",
        "}",
        "",
        "fn hu_expect_x(p, i): i64 { return hu_expect(p, i, 0); }",
        "fn hu_expect_y(p, i): i64 { return hu_expect(p, i, 1); }",
        "fn hu_expect_tag(p, i): i64 { return hu_expect(p, i, 2); }",
        "",
        "fn hu_expect_advance(p): i64 {",
    ]
    _pairs(L, ["if (p == %d) { return %d; }" % (p, r["advance"]) for p, r in enumerate(results)], 3)
    L += ["    return 0;", "}", ""]
    L += [
        "# The consumer-flow records (hu_expect2_* / hu_expect3_*): row p's hu_x<p>(k) chunks hold one",
        "# space-separated decimal text — glyph 2's record then glyph 3's, each `points contours advance",
        "# end.. x y tag..` (a glyph not recorded is the single number -1) — and hu_num(p, k) reads the",
        "# k-th number of it, counting across the chunks (a chunk boundary separates two numbers).",
        "fn hu_xchunk(p, k): i64 {",
    ]
    _pairs(L, ["if (p == %d) { return hu_x%d(k); }" % (p, p) for p in range(n)], 3)
    L += [
        "    return 0;",
        "}",
        "",
        "fn hu_num(p, k): i64 {",
        "    if (k < 0) { return 0; }",
        "    var seen = 0;",
        "    var c = 0;",
        "    var s = hu_xchunk(p, c);",
        "    while (s != 0) {",
        "        var j = 0;",
        "        while (load8(s + j) != 0) {",
        "            if (load8(s + j) == 32) {",
        "                j = j + 1;",
        "            } else {",
        "                var neg = 0;",
        "                if (load8(s + j) == 45) { neg = 1; j = j + 1; }",
        "                var v = 0;",
        "                while ((load8(s + j) >= 48) && (load8(s + j) <= 57)) {",
        "                    v = (v * 10) + (load8(s + j) - 48);",
        "                    j = j + 1;",
        "                }",
        "                if (neg == 1) { v = 0 - v; }",
        "                if (seen == k) { return v; }",
        "                seen = seen + 1;",
        "            }",
        "        }",
        "        c = c + 1;",
        "        s = hu_xchunk(p, c);",
        "    }",
        "    return 0;",
        "}",
        "",
        "# Where glyph 3's record starts: after glyph 2's `points contours advance`, its ends and its",
        "# points, or after the single -1.",
        "fn hu_rec3(p): i64 {",
        "    var n2 = hu_num(p, 0);",
        "    if (n2 < 0) { return 1; }",
        "    return 3 + hu_num(p, 1) + (3 * n2);",
        "}",
        "",
        "# The record at number offset `b`: field f 0 points, 1 contours, 2 advance; end c; point i's",
        "# x (0), y (1), tag (2). Out of range answers 0; a glyph not recorded answers -1 for points and",
        "# 0 for everything else.",
        "fn hu_rec_field(p, b, f): i64 {",
        "    if (hu_num(p, b) < 0) { if (f == 0) { return 0 - 1; } return 0; }",
        "    return hu_num(p, b + f);",
        "}",
        "",
        "fn hu_rec_end(p, b, c): i64 {",
        "    if (c < 0) { return 0; }",
        "    if (c >= hu_rec_field(p, b, 1)) { return 0; }",
        "    return hu_num(p, b + 3 + c);",
        "}",
        "",
        "fn hu_rec_point(p, b, i, f): i64 {",
        "    if (i < 0) { return 0; }",
        "    if (i >= hu_rec_field(p, b, 0)) { return 0; }",
        "    if (f < 0) { return 0; }",
        "    if (f > 2) { return 0; }",
        "    return hu_num(p, b + 3 + hu_num(p, b + 1) + (3 * i) + f);",
        "}",
        "",
        "fn hu_expect2_points(p): i64 { return hu_rec_field(p, 0, 0); }",
        "fn hu_expect2_contours(p): i64 { return hu_rec_field(p, 0, 1); }",
        "fn hu_expect2_advance(p): i64 { return hu_rec_field(p, 0, 2); }",
        "fn hu_expect2_end(p, c): i64 { return hu_rec_end(p, 0, c); }",
        "fn hu_expect2_x(p, i): i64 { return hu_rec_point(p, 0, i, 0); }",
        "fn hu_expect2_y(p, i): i64 { return hu_rec_point(p, 0, i, 1); }",
        "fn hu_expect2_tag(p, i): i64 { return hu_rec_point(p, 0, i, 2); }",
        "",
        "fn hu_expect3_points(p): i64 { return hu_rec_field(p, hu_rec3(p), 0); }",
        "fn hu_expect3_contours(p): i64 { return hu_rec_field(p, hu_rec3(p), 1); }",
        "fn hu_expect3_advance(p): i64 { return hu_rec_field(p, hu_rec3(p), 2); }",
        "fn hu_expect3_end(p, c): i64 { return hu_rec_end(p, hu_rec3(p), c); }",
        "fn hu_expect3_x(p, i): i64 { return hu_rec_point(p, hu_rec3(p), i, 0); }",
        "fn hu_expect3_y(p, i): i64 { return hu_rec_point(p, hu_rec3(p), i, 1); }",
        "fn hu_expect3_tag(p, i): i64 { return hu_rec_point(p, hu_rec3(p), i, 2); }",
        "",
    ]
    return L


def _lint_ok(path):
    """`cyrius lint <path> --strict` must exit 0 and print no warn/deferral line (the CI gate)."""
    r = subprocess.run(["cyrius", "lint", path, "--strict"], capture_output=True, text=True)
    out = r.stdout + r.stderr
    bad = [ln for ln in out.split("\n") if ln.lstrip().startswith(("warn ", "deferral "))]
    if r.returncode != 0 or bad:
        return "cyrius lint --strict: rc %d\n%s" % (r.returncode, out)
    return None


def _fmt_ok(path, tmpdir):
    """`cyrius fmt` on a COPY must change nothing (never --check: it is a false negative)."""
    copy = os.path.join(tmpdir, "fmt_copy.cyr")
    shutil.copyfile(path, copy)
    r = subprocess.run(["cyrius", "fmt", copy], capture_output=True, text=True)
    if r.returncode != 0:
        return "cyrius fmt: rc %d\n%s%s" % (r.returncode, r.stdout, r.stderr)
    a, b = open(path, "rb").read(), open(copy, "rb").read()
    if a != b:
        r2 = subprocess.run(["diff", path, copy], capture_output=True, text=True)
        return "cyrius fmt rewrote the output:\n%s" % r2.stdout
    return None


MAX_MODULE_BYTES = 900_000


def self_check(lines):
    """The static gates: 120 BYTES per line, no trailing whitespace, no deferral word, and the
    whole module under MAX_MODULE_BYTES (a generated file a reviewer still has to read)."""
    total = sum(len(line.encode()) + 1 for line in lines)
    assert total < MAX_MODULE_BYTES, "the module is %d bytes, the cap is %d" % (total, MAX_MODULE_BYTES)
    for k, line in enumerate(lines, 1):
        assert len(line.encode()) <= 120, "line %d is %d bytes" % (k, len(line.encode()))
        assert not line.endswith(" "), "line %d has trailing whitespace" % k
        for w in DEFERRAL_EXACT:
            assert w not in line, "line %d holds the deferral word %r" % (k, w)
        low = line.lower()
        for w in DEFERRAL_FOLDED:
            assert w not in low, "line %d holds the deferral word %r" % (k, w)


def emit(path):
    results = run_all()
    L = module_lines(results)
    self_check(L)
    src = "\n".join(L)
    tmpdir = tempfile.mkdtemp(prefix="hint_unit_vectors.")
    try:
        cand = os.path.join(tmpdir, os.path.basename(path))
        open(cand, "w").write(src)
        why = _lint_ok(cand) or _fmt_ok(cand, tmpdir)
        if why:
            sys.exit("refusing to write %s:\n%s" % (path, why))
        shutil.move(cand, path)
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)
    print("wrote %s: FreeType %s, %d fonts, %d programs (%d composite rows), %d lines, %d bytes (cap %d), "
          "lint --strict and fmt clean"
          % (path, ftshim.version_string(), len(FONTS), len(PROGRAMS), sum(1 for p in PROGRAMS if p["gid"] != 1), len(L),
             len(src.encode()), MAX_MODULE_BYTES))


def cmd_list(argv):
    results = run_all()
    print("# FreeType %s (%s), interpreter-version %d, %d fonts, %d programs, all clean under FT_LOAD_PEDANTIC"
          % (ftshim.version_string(), ftshim.library_path(), ftshim.INTERPRETER_VERSION, len(FONTS), len(PROGRAMS)))
    for f, fd in enumerate(FONTS):
        extra = ("  [%s]" % ", ".join(font_differs(f))) if font_differs(f) else ""
        print("# font %d %-13s prep: %s%s" % (f, fd["name"], fd["prep"], extra))
    for p, (prog, r) in enumerate(zip(PROGRAMS, results)):
        moved = sum(1 for i in range(r["n"]) if r["points"][i] != r["raw"][0][i] or r["tags"][i] != r["raw"][1][i])
        seq = " ".join("g%d:%s" % (g, "none" if r["seq"][g] is None else ("%d/%d%s" % (len(r["seq"][g][0]), r["seq"][g][3],
                                                                                    "*" if g in r["seq_carries"] else "")))
                       for g in (2, 3))
        print("%2d %-26s f%d g%d %3d ppem %3d B  %2d pts changed  adv %4d  [%s]  %s"
              % (p, prog["name"], prog["font"], prog["gid"], prog["ppem"], len(r["code"]) + len(r["comp"]), moved,
                 r["advance"], seq, prog["proves"]))


def cmd_dump(argv):
    if not argv:
        sys.exit("dump needs a program name; `list` shows them")
    names = [p["name"] for p in PROGRAMS]
    if argv[0] not in names:
        sys.exit("no program %r; `list` shows them" % argv[0])
    prog = PROGRAMS[names.index(argv[0])]
    r = run_program(prog)
    run_check(prog, r)
    print("%s — font %d, gid %d, %d ppem, %d bytes, advance %d: %s"
          % (prog["name"], prog["font"], prog["gid"], prog["ppem"], len(r["code"]), r["advance"], prog["proves"]))
    print("  " + "\n  ".join(disasm(r["code"])))
    print("  bytes: " + " ".join("%02X" % b for b in r["code"]))
    if r["comp"]:
        print("  composite: " + " ".join(disasm(r["comp"])))
    print("%4s %-16s %-16s %5s   %s" % ("i", "before", "after", "tag", "delta"))
    for i in range(r["n"]):
        a, b, t = r["raw"][0][i], r["points"][i], r["tags"][i]
        d = (b[0] - a[0], b[1] - a[1])
        print("%4d %-16s %-16s %5d %s %s" % (i, a, b, t, " *" if d != (0, 0) or t != r["raw"][1][i] else "  ", d if d != (0, 0) else ""))
    for g in (2, 3):
        rec = r["seq"][g]
        if rec is None:
            print("gid %d in the consumer flow: not recorded — %s" % (g, r["seq_why"][g]))
            continue
        pts, tags, ends, adv = rec
        print("gid %d in the consumer flow (after gid %s on one face): %d points, ends %s, advance %d%s"
              % (g, "1" if g == 2 else "1 and 2", len(pts), ends, adv,
                 " — DIFFERS from a fresh first load (state carried)" if g in r["seq_carries"] else ""))
        for i in range(len(pts)):
            print("%4d %-16s %5d" % (i, pts[i], tags[i]))


def main():
    cmds = {"emit": None, "list": cmd_list, "dump": cmd_dump}
    if len(sys.argv) < 2 or sys.argv[1] not in cmds:
        print(__doc__)
        return 2
    if sys.argv[1] == "emit":
        emit(sys.argv[2] if len(sys.argv) > 2 else "programs/hint_unit_vectors.cyr")
        return 0
    return cmds[sys.argv[1]](sys.argv[2:]) or 0


if __name__ == "__main__":
    sys.exit(main())
